@push('scripts')
<script>$(function(){var t=$('#finance-reconciliation-report'),branch=$('#reconciliation-branch'),from=$('#reconciliation-from'),to=$('#reconciliation-to'),exceptions=$('#reconciliation-exceptions'),x=$.fn.dataTable.render.text(),money=$.fn.dataTable.render.number(',','.',2);var dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.branch_scope=branch.val();d.from=from.val();d.to=to.val();d.exceptions_only=exceptions.val()}},order:[[0,'asc']],buttons:[window.erpExcelButton(t,function(){return{branch_scope:branch.val(),from:from.val(),to:to.val(),exceptions_only:exceptions.val()}})],columns:[{data:'source_label',name:'source_type',render:function(v,t,r){return r.source_url?'<a href="'+x.display(r.source_url)+'">'+x.display(v)+'</a>':x.display(v)}},{data:'source_count',name:'source_count',className:'text-end',render:x.display},{data:'journal_count',name:'journal_count',className:'text-end',render:x.display},{data:'debit_total',name:'debit_total',className:'text-end',render:money},{data:'credit_total',name:'credit_total',className:'text-end',render:money},{data:'difference',name:'difference',className:'text-end',render:money},{data:'missing_journal_count',name:'missing_journal_count',className:'text-end',render:x.display},{data:'unbalanced_journal_count',name:'unbalanced_journal_count',className:'text-end',render:x.display},{data:'balanced',name:'balanced',render:function(v){return '<span class="badge '+(v==='สมดุล'?'app-status-success':'app-status-danger')+'">'+x.display(v)+'</span>';}}]}));branch.add(from).add(to).add(exceptions).on('change',function(){dt.ajax.reload()});$('#reconciliation-reset').on('click',function(){branch.val('current');from.val('');to.val('');exceptions.val('0');dt.ajax.reload()});});</script>
